import API from "../api.js";
import { useEffect, useState } from "react";
import axios from "axios";
import { Printer } from "lucide-react";

const MONTH_NAMES = ["","January","February","March","April","May","June","July","August","September","October","November","December"];

const selectStyle = {
  background: "var(--bg-surface)", color: "var(--text-primary)",
  border: "1px solid var(--border-default)", borderRadius: "var(--radius-md)",
  padding: "10px 36px 10px 14px", fontSize: "14px", fontFamily: "inherit",
  appearance: "none",
  backgroundImage: "url(\"data:image/svg+xml,%3Csvg xmlns='https://www.w3.org/2000/svg' width='12' height='12' viewBox='0 0 24 24' fill='none' stroke='%2386868b' stroke-width='2'%3E%3Cpolyline points='6 9 12 15 18 9'%3E%3C/polyline%3E%3C/svg%3E\")",
  backgroundRepeat: "no-repeat", backgroundPosition: "right 12px center",
};

function printPayslip(emp, month, year) {
  const monthName = MONTH_NAMES[month];
  const logo = "data:image/png;base64,";
  const generatedOn = new Date().toLocaleDateString("en-IN", { day: "2-digit", month: "long", year: "numeric" });
  const win = window.open("", "_blank");
  win.document.write(`
    <!DOCTYPE html><html><head>
    <title>Payslip — ${emp.name} — ${monthName} ${year}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
      * { box-sizing: border-box; margin: 0; padding: 0; }
      body { font-family: "Inter", -apple-system, sans-serif; color: #111; background: #fff; }

      /* ── Header ── */
      .header {
        background: #f97020;
        padding: 20px 36px;
        display: flex;
        align-items: center;
        justify-content: space-between;
      }
      .header-left { display: flex; align-items: center; gap: 14px; }
      .logo { height: 52px; width: auto; display: block; }
      .company-name { color: #fff; font-size: 20px; font-weight: 700; letter-spacing: -0.02em; }
      .company-sub { color: rgba(255,255,255,0.75); font-size: 10px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; margin-top: 3px; }
      .header-right { text-align: right; }
      .payslip-label { color: #fff; font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }
      .payslip-period { color: rgba(255,255,255,0.8); font-size: 12px; margin-top: 3px; letter-spacing: 0.02em; }

      /* ── Employee strip ── */
      .emp-strip {
        background: #1c1c1e;
        padding: 16px 36px;
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 0;
      }
      .emp-item { padding: 0 20px 0 0; border-right: 1px solid rgba(255,255,255,0.1); }
      .emp-item:first-child { padding-left: 0; }
      .emp-item:last-child { border-right: none; }
      .emp-label { font-size: 9px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: rgba(255,255,255,0.45); margin-bottom: 4px; }
      .emp-value { font-size: 14px; font-weight: 600; color: #fff; }

      /* ── Body ── */
      .body { padding: 28px 36px; }

      /* ── Earnings table ── */
      .section-title {
        font-size: 10px; font-weight: 700; letter-spacing: 0.1em;
        text-transform: uppercase; color: #71717a;
        margin-bottom: 10px; margin-top: 24px;
      }
      .section-title:first-child { margin-top: 0; }

      table { width: 100%; border-collapse: collapse; }
      thead tr { background: #f4f4f5; }
      th {
        padding: 9px 14px; text-align: left;
        font-size: 10px; font-weight: 600;
        text-transform: uppercase; letter-spacing: 0.06em; color: #71717a;
      }
      th:last-child { text-align: right; }
      td { padding: 11px 14px; border-bottom: 1px solid #f0f0f0; font-size: 13px; color: #333; }
      td:last-child { text-align: right; font-weight: 500; }
      tr:last-child td { border-bottom: none; }
      tr.total-row td { background: #f9f9f9; font-weight: 700; font-size: 15px; border-top: 2px solid #e4e4e7; }

      /* ── Payment summary ── */
      .summary-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 12px;
        margin-top: 24px;
      }
      .summary-box {
        border-radius: 10px;
        padding: 16px 18px;
        border: 1px solid #e4e4e7;
      }
      .summary-box.paid { background: #f0fdf4; border-color: #bbf7d0; }
      .summary-box.remaining { background: #fffbeb; border-color: #fde68a; }
      .summary-box.excess { background: #faf5ff; border-color: #e9d5ff; }
      .summary-label {
        font-size: 9px; font-weight: 700; letter-spacing: 0.1em;
        text-transform: uppercase; margin-bottom: 6px;
      }
      .summary-box.paid .summary-label { color: #15803d; }
      .summary-box.remaining .summary-label { color: #b45309; }
      .summary-box.excess .summary-label { color: #7c3aed; }
      .summary-amount { font-size: 22px; font-weight: 700; }
      .summary-box.paid .summary-amount { color: #16a34a; }
      .summary-box.remaining .summary-amount { color: #d97706; }
      .summary-box.excess .summary-amount { color: #9333ea; }

      /* ── Footer ── */
      .footer {
        background: #f97020;
        padding: 10px 36px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-top: 32px;
      }
      .footer span { font-size: 10px; color: rgba(255,255,255,0.85); }

      @media print {
        body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
      }
    </style>
    </head>
    <body>

      <!-- Header -->
      <div class="header">
        <div class="header-left">
          <img src="${logo}" class="logo" alt="Kshethropasana" />
          <div>
            <div class="company-name">Kshethropasana</div>
            <div class="company-sub">Temple Construction</div>
          </div>
        </div>
        <div class="header-right">
          <div class="payslip-label">Payslip</div>
          <div class="payslip-period">${monthName} ${year}</div>
        </div>
      </div>

      <!-- Employee strip -->
      <div class="emp-strip">
        <div class="emp-item">
          <div class="emp-label">Employee</div>
          <div class="emp-value">${emp.name}</div>
        </div>
        <div class="emp-item">
          <div class="emp-label">Department</div>
          <div class="emp-value">${emp.department}</div>
        </div>
        <div class="emp-item">
          <div class="emp-label">Daily Wage</div>
          <div class="emp-value">₹${emp.wage}</div>
        </div>
        <div class="emp-item">
          <div class="emp-label">Days Present</div>
          <div class="emp-value">${emp.presentDays} days</div>
        </div>
      </div>

      <!-- Body -->
      <div class="body">

        <div class="section-title">Earnings &amp; Deductions</div>
        <table>
          <thead>
            <tr><th>Description</th><th>Amount</th></tr>
          </thead>
          <tbody>
            <tr>
              <td>Gross Salary (${emp.presentDays} days × ₹${emp.wage})</td>
              <td>₹${emp.grossSalary?.toLocaleString()}</td>
            </tr>
            ${emp.totalOvertime > 0 ? `<tr><td>Overtime</td><td style='color:#0a84ff'>+ ₹${emp.totalOvertime?.toLocaleString()}</td></tr>` : ''}
            ${emp.totalAdvance > 0 ? `<tr><td>Advance Deduction</td><td style='color:#ef4444'>− ₹${emp.totalAdvance?.toLocaleString()}</td></tr>` : ''}
            <tr class="total-row">
              <td>Net Salary</td>
              <td style="color:${emp.netSalary >= 0 ? "#16a34a" : "#dc2626"}">₹${emp.netSalary?.toLocaleString()}</td>
            </tr>
          </tbody>
        </table>

        <!-- Payment summary -->
        <div class="summary-grid">
          <div class="summary-box paid">
            <div class="summary-label">Total Paid</div>
            <div class="summary-amount">₹${emp.totalPaid?.toLocaleString()}</div>
          </div>
          ${emp.remaining > 0 ? `
          <div class="summary-box remaining">
            <div class="summary-label">Remaining Balance</div>
            <div class="summary-amount">₹${emp.remaining?.toLocaleString()}</div>
          </div>` : ""}
          ${emp.excess > 0 ? `
          <div class="summary-box excess">
            <div class="summary-label">Excess Paid</div>
            <div class="summary-amount">₹${emp.excess?.toLocaleString()}</div>
          </div>` : ""}
        </div>

      </div>

      <!-- Footer -->
      <div class="footer">
        <span>Kshethropasana Payroll Management System</span>
        <span>Generated on ${generatedOn}</span>
      </div>

      <script>window.onload = () => { window.print(); }</script>
    </body></html>
  `);
  win.document.close();
}

function Payroll() {
  const [payroll, setPayroll] = useState([]);
  const [month, setMonth] = useState(new Date().getMonth() + 1);
  const [year, setYear] = useState(new Date().getFullYear());
  const [filterEmployee, setFilterEmployee] = useState("");
  const [filterDept, setFilterDept] = useState(""); // single dept
  const [excludedDepts, setExcludedDepts] = useState(new Set()); // multi-exclude
  const [showDeptPanel, setShowDeptPanel] = useState(false);
  const [projects, setProjects] = useState([]);
  const [filterProject, setFilterProject] = useState("");

  useEffect(() => { fetchPayroll(); fetchProjects(); }, [month, year, filterProject]);

  async function fetchProjects() {
    try { const r = await axios.get(`${API}/api/projects`); setProjects(r.data); } catch(e) {}
  }

  async function fetchPayroll() {
    try {
      const r = await axios.get(`${API}/api/payroll?month=${month}&year=${year}${filterProject ? '&project=' + encodeURIComponent(filterProject) : ''}`);
      setPayroll(r.data);
    } catch (e) { console.log(e); }
  }

  const departments = [...new Set(payroll.map(e => e.department))].sort();
  const filtered = payroll.filter(e => {
    if (filterEmployee && String(e.id) !== filterEmployee) return false;
    if (filterDept && e.department !== filterDept) return false;
    if (excludedDepts.size > 0 && excludedDepts.has(e.department)) return false;
    return true;
  });
  const totalNet = filtered.reduce((s, e) => s + e.netSalary, 0);
  const totalPaid = filtered.reduce((s, e) => s + e.totalPaid, 0);
  const totalRemaining = filtered.reduce((s, e) => s + e.remaining, 0);
  const selectedEmployee = filterEmployee ? payroll.find((e) => String(e.id) === filterEmployee) : null;

  function toggleExclude(dept) {
    setExcludedDepts(prev => {
      const next = new Set(prev);
      if (next.has(dept)) next.delete(dept); else next.add(dept);
      return next;
    });
  }

  return (
    <>
      <div style={{ marginBottom: `32px` }}>
        <h1>Payroll</h1>
        <p className="dashboard-subtitle">Monthly salary calculation and payment tracking</p>
      </div>

      <div style={{ display: "flex", gap: "12px", marginBottom: "24px", flexWrap: "wrap", alignItems: "center" }}>
        <select value={month} onChange={(e) => setMonth(e.target.value)} style={selectStyle}>
          {MONTH_NAMES.slice(1).map((n, i) => <option key={i+1} value={i+1}>{n}</option>)}
        </select>
        <select value={year} onChange={(e) => setYear(e.target.value)} style={selectStyle}>
          {Array.from({ length: 20 }, (_, i) => { const y = new Date().getFullYear() - 5 + i; return <option key={y} value={y}>{y}</option>; })}
        </select>
        {/* Department filter */}
        <select value={filterDept} onChange={e => { setFilterDept(e.target.value); setFilterEmployee(""); setExcludedDepts(new Set()); }}
          style={{ ...selectStyle, minWidth: "170px", borderColor: filterDept ? "var(--accent)" : "var(--border-default)", boxShadow: filterDept ? "0 0 0 3px var(--accent-glow)" : "none" }}>
          <option value="">All Departments</option>
          {departments.map(d => <option key={d} value={d}>{d}</option>)}
        </select>

        {/* Employee filter */}
        <select value={filterEmployee} onChange={e => { setFilterEmployee(e.target.value); setFilterDept(""); setExcludedDepts(new Set()); }}
          style={{ ...selectStyle, minWidth: "190px", borderColor: filterEmployee ? "var(--accent)" : "var(--border-default)", boxShadow: filterEmployee ? "0 0 0 3px var(--accent-glow)" : "none" }}>
          <option value="">All Employees</option>
          {payroll.filter(e => !filterDept || e.department === filterDept).map(emp => <option key={emp.id} value={String(emp.id)}>{emp.name}</option>)}
        </select>

        {/* Project filter */}
        {!filterEmployee && (
          <select value={filterProject} onChange={e => { setFilterProject(e.target.value); setFilterDept(""); setFilterEmployee(""); setExcludedDepts(new Set()); }}
            style={{ ...selectStyle, minWidth: "160px", borderColor: filterProject ? "var(--accent)" : "var(--border-default)", boxShadow: filterProject ? "0 0 0 3px var(--accent-glow)" : "none" }}>
            <option value="">All Projects</option>
            {projects.map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
          </select>
        )}

        {/* Exclude departments button */}
        {!filterEmployee && !filterDept && !filterProject && (
          <div style={{ position: "relative" }}>
            <button onClick={() => setShowDeptPanel(p => !p)}
              style={{ ...selectStyle, minWidth: "auto", padding: "10px 16px", cursor: "pointer",
                borderColor: excludedDepts.size > 0 ? "var(--red)" : "var(--border-default)",
                boxShadow: excludedDepts.size > 0 ? "0 0 0 3px rgba(255,69,58,0.15)" : "none",
                background: excludedDepts.size > 0 ? "rgba(255,69,58,0.08)" : "var(--bg-surface)",
                color: excludedDepts.size > 0 ? "var(--red)" : "var(--text-secondary)",
              }}>
              {excludedDepts.size > 0 ? `Excluding ${excludedDepts.size} Dept${excludedDepts.size > 1 ? "s" : ""}` : "Exclude Departments"}
            </button>
            {showDeptPanel && (
              <div style={{ position: "absolute", top: "calc(100% + 8px)", left: 0, zIndex: 100,
                background: "var(--bg-surface)", border: "1px solid var(--border-default)",
                borderRadius: "var(--radius-lg)", padding: "12px", minWidth: "220px",
                boxShadow: "0 8px 32px rgba(0,0,0,0.4)" }}>
                <p style={{ fontSize: "11px", fontWeight: "600", color: "var(--text-tertiary)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: "10px" }}>
                  Uncheck to exclude from payroll
                </p>
                {departments.map(dept => (
                  <label key={dept} style={{ display: "flex", alignItems: "center", gap: "10px", padding: "8px 4px", cursor: "pointer", borderRadius: "6px" }}>
                    <input type="checkbox" checked={!excludedDepts.has(dept)} onChange={() => toggleExclude(dept)}
                      style={{ width: "15px", height: "15px", accentColor: "var(--accent)", cursor: "pointer" }} />
                    <span style={{ fontSize: "13px", color: excludedDepts.has(dept) ? "var(--text-tertiary)" : "var(--text-primary)",
                      textDecoration: excludedDepts.has(dept) ? "line-through" : "none" }}>{dept}</span>
                  </label>
                ))}
                <div style={{ marginTop: "10px", paddingTop: "10px", borderTop: "1px solid var(--border-subtle)", display: "flex", gap: "8px" }}>
                  <button onClick={() => { setExcludedDepts(new Set()); setShowDeptPanel(false); }}
                    className="secondary-btn" style={{ fontSize: "12px", padding: "6px 12px", flex: 1 }}>Reset</button>
                  <button onClick={() => setShowDeptPanel(false)}
                    className="add-btn" style={{ fontSize: "12px", padding: "6px 12px", flex: 1 }}>Done</button>
                </div>
              </div>
            )}
          </div>
        )}

        {(filterEmployee || filterDept || excludedDepts.size > 0 || filterProject) && (
          <button onClick={() => { setFilterEmployee(""); setFilterDept(""); setExcludedDepts(new Set()); setFilterProject(""); }} className="secondary-btn" style={{ padding: "10px 16px", fontSize: "13px" }}>✕ Clear</button>
        )}

        {/* Print payslip button — only when single employee selected */}
        {filterEmployee && filtered.length === 1 && (
          <button className="add-btn" onClick={() => printPayslip(filtered[0], month, year)}
            style={{ display: "flex", alignItems: "center", gap: "6px", marginLeft: "auto" }}>
            <Printer size={14} /> Print Payslip
          </button>
        )}
      </div>

      {selectedEmployee && (
        <div style={{ marginBottom: "20px", display: "flex", alignItems: "center", gap: "10px" }}>
          <span style={{ fontSize: "13px", color: "var(--text-secondary)" }}>Viewing payroll for:</span>
          <span className="badge badge-blue" style={{ fontSize: "13px", padding: "5px 14px" }}>
            {selectedEmployee.name} — {selectedEmployee.department}
          </span>
        </div>
      )}

      {filtered.length > 0 && (
        <div className="dashboard-cards" style={{ marginBottom: "24px" }}>
          {!filterEmployee && <div className="card"><h2>Employees</h2><h1>{filtered.length}</h1></div>}
          {filterEmployee && <div className="card"><h2>Present Days</h2><h1>{filtered[0]?.presentDays}</h1></div>}
          <div className="card"><h2>{filterEmployee ? "Gross Salary" : "Total Gross"}</h2><h1 style={{ fontSize: "26px" }}>₹{filtered.reduce((s,e)=>s+e.grossSalary,0).toLocaleString()}</h1></div>
          <div className="card"><h2>{filterEmployee ? "Net Salary" : "Total Net"}</h2><h1 style={{ color: "var(--green)", fontSize: "26px" }}>₹{totalNet.toLocaleString()}</h1></div>
          <div className="card"><h2>{filterEmployee ? "Paid" : "Total Paid"}</h2><h1 style={{ color: "var(--accent)", fontSize: "26px" }}>₹{totalPaid.toLocaleString()}</h1></div>
          <div className="card"><h2>Remaining</h2><h1 style={{ color: "var(--amber)", fontSize: "26px" }}>₹{totalRemaining.toLocaleString()}</h1></div>
        </div>
      )}

      <div className="table-container" style={{ overflowX: "auto" }}>
        <table className="employee-table">
          <thead>
            <tr><th>Employee</th><th>Dept</th><th>Wage/Day</th><th>Days Present</th><th>Gross</th><th>Overtime</th><th>Advances</th><th>Early Leave</th><th>Net Salary</th><th>Total Paid</th><th>Remaining</th><th>Excess</th><th>Payslip</th></tr>
          </thead>
          <tbody>
            {filtered.length === 0 ? (
              <tr><td colSpan={13} className="empty-state">{payroll.length === 0 ? `No payroll data for ${MONTH_NAMES[month]} ${year}` : "No employee found"}</td></tr>
            ) : filtered.map((emp) => (
              <tr key={emp.id}>
                <td style={{ fontWeight: "600" }}>{emp.name}</td>
                <td style={{ color: "var(--text-secondary)" }}>{emp.department}</td>
                <td>₹{emp.wage}</td>
                <td>{emp.presentDays}</td>
                <td>₹{Math.round(emp.grossSalary).toLocaleString()}</td>
                <td style={{ color: "var(--accent)" }}>₹{Math.round(emp.totalOvertime).toLocaleString()}</td>
                <td style={{ color: "var(--amber)" }}>₹{Math.round(emp.totalAdvance).toLocaleString()}</td>
                <td style={{ color: "var(--red)" }}>{emp.totalEarlyLeave > 0 ? `−₹${emp.totalEarlyLeave?.toLocaleString()}` : "—"}</td>
                <td><span className={`badge ${emp.netSalary >= 0 ? "badge-green" : "badge-red"}`}>₹{Math.round(emp.netSalary).toLocaleString()}</span></td>
                <td><span className="badge badge-blue">₹{Math.round(emp.totalPaid).toLocaleString()}</span></td>
                <td>{emp.remaining > 0 ? <span className="badge badge-amber">₹{Math.round(emp.remaining).toLocaleString()}</span> : <span style={{ color: "var(--text-tertiary)" }}>—</span>}</td>
                <td>{emp.excess > 0 ? <span className="badge badge-purple">₹{Math.round(emp.excess).toLocaleString()}</span> : <span style={{ color: "var(--text-tertiary)" }}>—</span>}</td>
                <td>
                  <button className="secondary-btn" style={{ padding: "6px 12px", fontSize: "12px", display: "flex", alignItems: "center", gap: "4px" }} onClick={() => printPayslip(emp, month, year)}>
                    <Printer size={12} /> Print
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {filtered.length > 0 && (
        <div style={{ display: "flex", gap: "20px", marginTop: "16px", flexWrap: "wrap" }}>
          <span className="badge badge-green">Net Salary</span>
          <span className="badge badge-blue">Total Paid</span>
          <span className="badge badge-amber">Remaining</span>
          <span className="badge badge-purple">Excess Paid</span>
        </div>
      )}
    </>
  );
}

export default Payroll;
